### Minimal runnable check

```bash
# save sourcemap-transcoder.js from §2, then:
node -e '
const { SourceMap, originalPositionForChain, transcode } = require("./sourcemap-transcoder.js");
const m1 = new SourceMap({version:3,sources:["transpiled.js"],names:["m1"],mappings:"UAAAA,VAEG,U;K"});
const m2 = new SourceMap({version:3,sources:["original.ts"],names:["origName"],mappings:"AACIA;;GAMK"});
const chain = originalPositionForChain([m1,m2], {line:1,column:11});
const comp  = transcode(m1,m2).originalPositionFor({line:1,column:11});
console.assert(JSON.stringify(chain) === JSON.stringify(comp), "composition mismatch");
console.assert(chain.source === "original.ts" && chain.line === 2 && chain.column === 4 && chain.name === "origName");
console.assert(new SourceMap({version:3,sources:["x"],names:[],mappings:"AAKK,AAJJ"}).originalPositionFor({line:1,column:0}).column === 5, "stable tie order");
